      let pendingWrites = 0;
      const pendingWritesByStream: Record<'stdout' | 'stderr', number> = { stdout: 0, stderr: 0 };
      const releaseLateContainment: Record<'stdout' | 'stderr', (() => void) | null> = { stdout: null, stderr: null };
      let onDrained: (() => void) | null = null;
      let listenersAttached = false;
      let listenerCleanupRequested = false;
      const releaseStreamErrorListeners = (): void => {
        if (!listenerCleanupRequested || !listenersAttached) return;
        // The drain cap bounds command lifetime, not EPIPE containment. Move
        // each still-pending write onto the bounded shared guard before removing
        // this run's listeners; otherwise permanently wedged streams accumulate
        // two listeners per foreground command forever.
        for (const streamName of ['stdout', 'stderr'] as const) {
          if (pendingWritesByStream[streamName] > 0 && !releaseLateContainment[streamName]) {
            releaseLateContainment[streamName] = retainLateStreamErrorContainment(streamName === 'stdout' ? stdout : stderr);
          }
        }
        stdout.removeListener('error', onStdoutError);
        stderr.removeListener('error', onStderrError);
        listenersAttached = false;
      };
      const releaseLateContainmentAfterErrorEvent = (streamName: 'stdout' | 'stderr'): void => {
        const release = releaseLateContainment[streamName];
        if (!release) return;
        // A real Writable may invoke write(cb) before it emits the matching
        // EPIPE 'error' event on a later next-tick. A promise continuation can
        // run before that next-tick when the write callback settles an async
        // host_run, so retain through the next event-loop turn instead. This
        // still releases promptly for successful writes.
        setImmediate(() => {
          if (pendingWritesByStream[streamName] !== 0 || releaseLateContainment[streamName] !== release) return;
          releaseLateContainment[streamName] = null;
          release();
        });
      };
      const settleWrite = (streamName: 'stdout' | 'stderr'): void => {
        pendingWrites -= 1;
        pendingWritesByStream[streamName] -= 1;
        if (pendingWritesByStream[streamName] <= 0) {
          pendingWritesByStream[streamName] = 0;
          releaseLateContainmentAfterErrorEvent(streamName);
        }
        if (pendingWrites <= 0) {
          pendingWrites = 0;
          if (onDrained) {
            const notify = onDrained;
            onDrained = null;
            notify();
          }
          releaseStreamErrorListeners();
        }
      };
      // Defensive cap: a genuinely WEDGED stream (a write that neither flushes nor
      // errors) must never hang host_run. If the cap wins, host_run still returns
      // boundedly, but listener removal waits for the eventual write settlement so
      // a post-return EPIPE cannot crash the foreground CLI.
      const drainCapMs = options.streamWriteDrainCapMs ?? 2000;
      const drainPending = (): Promise<void> => {
        if (pendingWrites <= 0) return Promise.resolve();
        return new Promise<void>((resolve) => {
          let settled = false;
          const timer = setTimeout(() => {
    let errorHandler: ((error: NodeJS.ErrnoException) => void) | null = null;
    let closeHandler: ((code: number | null, signal: NodeJS.Signals | null) => void) | null = null;

    // F-008: a throwing onChunk (e.g. EPIPE from a closed consumer pipe) must
    // never escape a 'data' listener as an uncaught EventEmitter exception —
    // that would crash the process, orphan the child, and leak the concurrency
    // slot. First failure flips the flag: delivery stops (no per-chunk retry),
    // chunks keep flowing to the usage scanner, and the run finishes normally
    // with the failure surfaced on the result.
    let passthroughBroken = false;
    let passthroughError: string | null = null;
    const deliver = (chunk: HostRunChunk): void => {
      if (passthroughBroken || !plan.onChunk) return;
      try {
        plan.onChunk(chunk);
      } catch (err) {
        passthroughBroken = true;
        passthroughError = err instanceof Error ? err.message : String(err);
      }
    };

    const clearTimersAndListener = (): void => {
      if (startupTimer) cancel(startupTimer);
      if (totalTimer) cancel(totalTimer);
      if (killTimer) cancel(killTimer);
      startupTimer = null;
      totalTimer = null;
      killTimer = null;
      if (abortListener && plan.signal) plan.signal.removeEventListener('abort', abortListener);
      abortListener = null;
    };
    const fenceDeadlineAfterClose = (): void => {
      // The close event is the child process's authoritative terminal boundary.
      // Its process-group cleanup may await after this point, but an already
      // queued deadline/abort callback must not rewrite a successful/failed
      // child close into a contradictory timeout result during that cleanup.
      if (startupTimer) cancel(startupTimer);
      if (totalTimer) cancel(totalTimer);
      startupTimer = null;
      totalTimer = null;
      if (abortListener && plan.signal) plan.signal.removeEventListener('abort', abortListener);
      abortListener = null;
    };
    const detachChildListeners = (): void => {
      if (!child) return;
      if (stdoutHandler) child.stdout?.removeListener('data', stdoutHandler);
      if (stderrHandler) child.stderr?.removeListener('data', stderrHandler);
      if (stdinErrorHandler) child.stdin?.removeListener?.('error', stdinErrorHandler);
      if (errorHandler) child.removeListener('error', errorHandler);
      if (closeHandler) child.removeListener('close', closeHandler);
      stdoutHandler = null;
      stderrHandler = null;
      stdinErrorHandler = null;
      errorHandler = null;
      closeHandler = null;
    };
    const finish = (exitCode: number): void => {
      if (settled) return;
      settled = true;
      clearTimersAndListener();
      scanner.flush();
      failureScanner.flush();
      finalResultScanner.flush();
      detachChildListeners();
      const finalResult = finalResultScanner.snapshot();
      resolve({
        stdout: scanner.retainedText(),
        stderr: retainedStderr,
        exitCode,
        timedOut,
        closeObserved,
        timeoutKind,
        terminalReason,
        firstOutputMs,
        durationMs: Math.max(0, Date.now() - startedAt),
        failureKind,
        retentionTruncated: scanner.truncated,
        failureText: failureScanner.retainedText(),
        // B-3ddc (codex round-1 F1): honor the failure lane's own truncation.
        failureRetentionTruncated: failureScanner.truncated,
        finalAssistantResult: finalResult.result,
        finalAssistantResultCount: finalResult.count,
        finalAssistantResultTruncated: finalResult.truncated,
        passthroughError,
        processIdentity,
        replacementSafe,
        residualProcessGroup,
        processCleanup: processIdentity
          ? { termSent, killSent, reaped: replacementSafe, residualProcessGroup }
          : null,
      });
    };

    try {
      child = (runtime.spawnChild ?? spawn)(plan.command, plan.argv, {
        cwd: plan.cwd,
        env: plan.reviewInvocationPayload
          ? { ...plan.env, LATTICE_MANAGED_REVIEW_INVOCATION_FD: '3' }
          : plan.env,
        stdio: plan.reviewInvocationPayload
          ? ['pipe', 'pipe', 'pipe', 'pipe']
          : ['pipe', 'pipe', 'pipe'],
        detached: processGroupIsolated,
      });
    } catch {
      terminalReason = 'spawn_error';
      failureKind = 'unknown';
      finish(1);
      return;
    }

    if (child.pid) {
      const spawnedAt = new Date().toISOString();
      processIdentity = {
        pid: child.pid,
        pgid: processGroupIsolated ? child.pid : null,
        spawnedAt,
        // When ps is hidden by a brokered sandbox, retain an exact
        // spawn-observation fingerprint bound to pid+time. It cannot authorize
        // PGID discovery, but the worker-signed descriptor can bind this exact
        // invocation without pretending ancestry was observable.
        startFingerprint: processGroupIsolated
          ? readStartFingerprint(child.pid) ?? `spawn-observed:${child.pid}:${spawnedAt}`
          : null,
        processGroupIsolated,
      };
    }

    const terminate = (reason: 'startup_no_output_timeout' | 'total_timeout' | 'aborted'): void => {
      if (settled || closeObserved || timeoutKind !== null || terminalReason === 'aborted') return;
      if (reason === 'aborted') {
        terminalReason = 'aborted';
      } else {
        timedOut = true;
        timeoutKind = reason;
        terminalReason = reason;
        failureKind = preferredHostFailure(failureKind, 'timeout');
      }
      clearTimersAndListener();
      if (processIdentity?.processGroupIsolated) {
        const sentToGroup = signalIsolatedProcessGroup(processIdentity, 'SIGTERM', readStartFingerprint, signalGroup);
        termSent = sentToGroup || termSent;
        // An unobservable/mismatched group leader is never safe to signal by
        // PGID. Still terminate the Node-owned direct child so a timeout cannot
        // hang forever; any surviving descendants are discovered below and keep
        // replacementSafe=false rather than being mistaken for a reaped group.
        if (!sentToGroup) {
          try { termSent = child?.kill('SIGTERM') === true || termSent; } catch { /* close/reap remains authoritative */ }
        }
        killTimer = schedule(() => {
          const killedGroup = signalIsolatedProcessGroup(processIdentity, 'SIGKILL', readStartFingerprint, signalGroup);
          killSent = killedGroup || killSent;
          if (!killedGroup) {
            try { killSent = child?.kill('SIGKILL') === true || killSent; } catch { /* close/reap remains authoritative */ }
          }
        }, HOST_RUN_PROCESS_GROUP_TERM_GRACE_MS);
      } else {
        try {
          child?.kill('SIGTERM');
        } catch {
          // best-effort; settlement still waits for error/close
        }
      }
    };
    const markFirstOutput = (): void => {
      if (firstOutputMs !== null) return;
      firstOutputMs = Math.max(0, Date.now() - startedAt);
      if (startupTimer) cancel(startupTimer);
      startupTimer = null;
    };
    const observeFailureText = (stream: HostRunChunk['stream'], text: string): void => {
      if (!text) return;
      const combined = `${classificationTail[stream]}${text}`;
      const observed = classifyHostExecutionDiagnosticText(combined);
      classificationTail[stream] = combined.slice(-HOST_RUN_FAILURE_CLASSIFICATION_WINDOW);
      if (observed) {
        failureKind = preferredHostFailure(failureKind, observed);
      }
    };
    const failPromptDelivery = (
      channel: 'stdin' | 'review invocation descriptor',
      error: NodeJS.ErrnoException,
    ): void => {
      if (settled) return;
      terminalReason = 'child_error';
      failureKind = preferredHostFailure(failureKind, 'unknown');
      const detail = error.code ?? error.message ?? 'unknown';
      retainedStderr = `${retainedStderr}host_run ${channel} delivery failed: ${detail}`
        .slice(-HOST_RUN_FAILURE_TEXT_CAP);
      if (processIdentity?.processGroupIsolated) {
        const killedGroup = signalIsolatedProcessGroup(processIdentity, 'SIGKILL', readStartFingerprint, signalGroup);
        killSent = killedGroup || killSent;
        if (!killedGroup) {
          try { killSent = child?.kill('SIGKILL') === true || killSent; } catch { /* settlement remains close-owned */ }
        }
      } else {
        try { child?.kill('SIGKILL'); } catch { /* settlement remains close-owned */ }
      }
    };

    if (processIdentity && plan.onSpawn) {
      try {
        plan.onSpawn(processIdentity);
      } catch (error) {
        terminalReason = 'child_error';
        failureKind = preferredHostFailure(failureKind, 'unknown');
        retainedStderr = `${retainedStderr}host_run onSpawn failed: ${error instanceof Error ? error.message : String(error)}`
          .slice(-HOST_RUN_FAILURE_TEXT_CAP);
        if (processIdentity.processGroupIsolated) {
          const killedGroup = signalIsolatedProcessGroup(processIdentity, 'SIGKILL', readStartFingerprint, signalGroup);
          killSent = killedGroup || killSent;
          if (!killedGroup) {
            try { killSent = child?.kill('SIGKILL') === true || killSent; } catch { /* best-effort */ }
          }
        }
        else {
          try { child?.kill('SIGKILL'); } catch { /* best-effort */ }
        }
      }
    }

    if (processIdentity && plan.reviewInvocationPayload && terminalReason !== 'child_error') {
      try {
        const descriptor = child.stdio[3];
        if (!descriptor || !('end' in descriptor)) throw new Error('provider invocation descriptor fd 3 is unavailable');
        descriptorErrorHandler = error => failPromptDelivery('review invocation descriptor', error);
        descriptor.on?.('error', descriptorErrorHandler);
        descriptor.end(plan.reviewInvocationPayload(processIdentity));
      } catch (error) {
        failPromptDelivery('review invocation descriptor', error as NodeJS.ErrnoException);
      }
    }

    // Codex's canonical managed launcher consumes the prompt from stdin (`-`).
    // Other launchers receive an empty stdin exactly as before.
    stdinErrorHandler = error => failPromptDelivery('stdin', error);
    child.stdin?.on?.('error', stdinErrorHandler);
    try {
      child.stdin?.end(plan.stdinText ?? '');
    } catch (error) {
      failPromptDelivery('stdin', error as NodeJS.ErrnoException);
    }

    if (plan.startupTimeoutMs && plan.startupTimeoutMs > 0) {
      startupTimer = schedule(() => terminate('startup_no_output_timeout'), plan.startupTimeoutMs);
    }
    if (plan.timeoutMs && plan.timeoutMs > 0) {
      totalTimer = schedule(() => terminate('total_timeout'), plan.timeoutMs);
    }
    abortListener = () => terminate('aborted');
    if (plan.signal?.aborted) abortListener();
    else plan.signal?.addEventListener('abort', abortListener, { once: true });

    child.stdout?.setEncoding('utf8');
    stdoutHandler = (text: string) => {
      if (text.length > 0) markFirstOutput();
      deliver({ stream: 'stdout', text });
      observeFailureText('stdout', text);
      scanner.push(text);
      // B-3ddc: the failure lane sees the same live text; delivery above is
      // untouched (the lane only keeps a bounded copy, never suppresses).
      failureScanner.push(text);
      finalResultScanner.push(text);
    };
    child.stdout?.on('data', stdoutHandler);
    child.stderr?.setEncoding('utf8');
    stderrHandler = (text: string) => {
      if (text.length > 0) markFirstOutput();
      retainedStderr = `${retainedStderr}${text}`.slice(-HOST_RUN_FAILURE_TEXT_CAP);
      deliver({ stream: 'stderr', text });
      observeFailureText('stderr', text);
    };
    child.stderr?.on('data', stderrHandler);

    errorHandler = (error: NodeJS.ErrnoException) => {
      if (!timedOut && terminalReason !== 'aborted') {
        asyncSpawnError = error.code === 'ENOENT' || error.code === 'EACCES';
        terminalReason = asyncSpawnError ? 'spawn_error' : 'child_error';
        failureKind = preferredHostFailure(failureKind, error.code === 'ENOENT' ? 'missing_executable' : 'unknown');
      }
      // Node emits `close` after `error`; settle there so every spawned child
      // follows the same close/reap boundary before capacity can be released.
    };
    child.on('error', errorHandler);
    closeHandler = (code, signal) => {
      if (settled || closeObserved) return;
      closeObserved = true;
      fenceDeadlineAfterClose();
      runtime.onChildCloseObserved?.();
      if (!timedOut && terminalReason !== 'aborted' && terminalReason !== 'child_error' && terminalReason !== 'spawn_error') {
        failureKind = preferredHostFailure(failureKind, classifyHostExecutionFailure({
          error: undefined,
          signal,
          stderr: retainedStderr,
          stdout: scanner.retainedText(),
          status: code,
        }));
        terminalReason = typeof code === 'number' && code === 0 ? 'completed' : 'exit_nonzero';
      }
      const exitCode = timedOut
        ? 124
        : terminalReason === 'aborted'
          ? 130
          : asyncSpawnError || terminalReason === 'child_error' || terminalReason === 'spawn_error'
            ? 1
            : typeof code === 'number' && code >= 0 ? code : 1;
      void (async () => {
        if (processIdentity?.processGroupIsolated && groupAlive(processIdentity.pgid)) {
          termSent = signalVerifiedOrLeaderlessProcessGroup(
            processIdentity, 'SIGTERM', readStartFingerprint, groupLeaderless, signalGroup,
          ) || termSent;
          await new Promise(resolveWait => setTimeout(resolveWait, HOST_RUN_PROCESS_GROUP_TERM_GRACE_MS));
          if (groupAlive(processIdentity.pgid)) {
            killSent = signalVerifiedOrLeaderlessProcessGroup(
              processIdentity, 'SIGKILL', readStartFingerprint, groupLeaderless, signalGroup,
            ) || killSent;
            await new Promise(resolveWait => setTimeout(resolveWait, HOST_RUN_PROCESS_GROUP_KILL_GRACE_MS));
          }
          residualProcessGroup = groupAlive(processIdentity.pgid);
          replacementSafe = !residualProcessGroup;
        }
        finish(exitCode);
      })();
    };
    child.on('close', closeHandler);
  });
}

// ---------------------------------------------------------------------------
// Argv materialization (writes the claude prompt file when needed)
// ---------------------------------------------------------------------------

interface MaterializedLaunch {
  command: string;
  argv: string[];
  stdinText?: string;
  promptFile?: string;
  cleanup: () => void;
}

function materializeLaunch(args: HostRunArgs): MaterializedLaunch {
  if (args.launchProfile === 'cross_host_review_codex') {
    if (args.host !== 'codex') throw new Error('host_run: cross_host_review_codex profile requires host=codex');
    return {
      command: 'codex',
      argv: ['exec', '-s', 'read-only', '-C', args.cwd, '-'],
      stdinText: args.promptText,
      cleanup: () => {},
    };
  }
  const spec = canonicalReviewHostLauncherSpec(args.host);
  if (args.host === 'claude') {
    // Claude Code's tool sandbox permits file reads only beneath its working
    // directory. Formal managed reviewers therefore receive the authoritative
    // one-shot prompt from the ignored runtime tree inside that exact cwd;
    // ordinary host_run keeps its legacy OS-temp transport. The leaf created by
    // mkdtemp is private and the prompt itself remains mode 0600.
    const promptParent = args.launchProfile === 'managed_reviewer'
      ? join(args.cwd, '.lattice', 'runtime', 'host-run-prompts')
      : tmpdir();
    if (args.launchProfile === 'managed_reviewer') {
      mkdirSync(promptParent, { recursive: true, mode: 0o700 });
    }
    const dir = mkdtempSync(join(promptParent, 'lattice-host-run-'));
    const promptFile = join(dir, 'prompt.txt');
    writeFileSync(promptFile, args.promptText, { encoding: 'utf8', mode: 0o600 });
    const full = materializeLauncherArgv(spec, { promptFile });
    const argv = full.slice(1);
    if (args.launchProfile === 'managed_reviewer') {
      // A detached managed reviewer has no human terminal on which Claude can
      // approve its required inspection/Lattice commands. Scope this mode to
      // the signed managed-review profile; ordinary Claude runs retain policy.
      argv.splice(
        Math.max(0, argv.length - 1),
        0,
        '--permission-mode', 'bypassPermissions',
        '--json-schema', managedReviewClaudeJsonSchema(args),
      );
    }
    return {
      command: full[0],
        },
      });
      return {
        schemaVersion: proposal.schemaVersion,
        runId,
        conclusion: proposal.conclusion,
        authoredAt: proposal.authoredAt,
      };
    },

    managed_review_evidence_import(args: { runId?: string; receiptId?: string }) {
      assertOnlyKeys('managed_review_evidence_import', args as Record<string, unknown>, ['runId', 'receiptId']);
      const runId = args.runId?.trim() || '';
      const receiptId = args.receiptId?.trim() || '';
      if (!runId || !receiptId) throw new Error('managed_review_evidence_import: runId and receiptId are required; verdict overrides are not accepted');
      const managedRun = readManagedHostRunBinding(ctx.root, runId);
      if (!managedRun.storyId || !managedRun.reviewRunId || !managedRun.lane || managedRun.profile !== 'managed_reviewer') {
        throw new Error('managed_review_evidence_import: run is not an exact managed_reviewer binding');
      }
      assertCwdInWorktree(ctx.store, managedRun.storyId);
      const story = ctx.store.readStory(managedRun.storyId);
      const reviewRun = assertCurrentReviewRunForEvidence(
        ctx.store,
        story,
        ctx.root,
        managedRun.lane,
        managedRun.reviewRunId,
      );
      // ReviewRun's advisory freshness policy is deliberately permissive for
      // some consumers, but receipt import is an authority-creating write. It
      // must bind to the LIVE tree, not merely an old otherwise-valid review
      // tuple: once either head or material changed, re-dispatch/re-review is
      // required before a managed provider verdict can become gate evidence.
      const gitCwd = resolveGitCwd({
        store: ctx.store,
        storyId: managedRun.storyId,
        metadataRoot: ctx.root,
        projectRoot: ctx.root,
      });
      // This check deliberately remains a closure rather than a one-time
      // preflight. Receipt verification and lock acquisition can take long
      // enough for a concurrent commit to change the reviewed tree. Recheck
      // while both canonical persistence locks are held immediately before
      // admitting an existing receipt or writing any new evidence/binding.
      const assertLiveReviewMaterial = (): void => {
        const liveHeadHash = currentGitHead(gitCwd);
        const liveMaterialHash = currentMaterialHash(gitCwd, 'HEAD', ctx.root);
        if (!liveHeadHash || !liveMaterialHash
          || liveHeadHash !== reviewRun.headHash
          || liveMaterialHash !== reviewRun.materialHash) {
          throw new Error(
            `managed_review_evidence_import: live review material drift (head=${reviewRun.headHash}/${liveHeadHash ?? 'unavailable'}, `
            + `material=${reviewRun.materialHash}/${liveMaterialHash ?? 'unavailable'}); rerun the managed reviewer`,
          );
        }
      };
      const expected = {
        providerHost: managedRun.host,
        headHash: reviewRun.headHash,
        materialHash: reviewRun.materialHash,
        storyFilesHash: reviewRun.storyFilesHash ?? reviewRun.workspaceBinding?.storyFilesHash ?? '',
        promptHash: reviewRun.promptHash,
        envelopeId: reviewRun.envelopeId ?? null,
        managedPromptDigest: managedReviewerPromptDigest(reviewRun.workspaceBinding?.metadataRoot ?? ctx.root, reviewRun),
      };
      const sealedProposal = readManagedReviewEvidenceProposal(ctx.root, runId);
      const intake = createManagedReviewEvidenceBinding({
        root: ctx.root,
        storyId: managedRun.storyId,
        providerAgent: managedRun.agentType,
        lane: managedRun.lane,
        reviewRunId: managedRun.reviewRunId,
        runId,
        receiptId,
        expected,
        // The import transaction identity must survive a crash after sealing
        // evidence-binding.json but before story metadata persistence. Bind its
        // timestamp to the immutable provider proposal rather than a retry-local
        // wall clock so the same receipt reconstructs byte-identical evidence.
        importedAt: sealedProposal?.authoredAt,
      });
      const proposal = intake.verification.proposal ?? sealedProposal;
      if (!proposal) throw new Error('managed_review_evidence_import: shared Proof Admissibility accepted no provider proposal');
      const lockDir = ctx.store.runtimeLockDirPath(proposal.storyId, 'managed-review-evidence', receiptId.replace(/[^A-Za-z0-9._-]/g, '_'));
      // The receipt lock makes replay of one receipt idempotent. A second,
      // story-level lock is still required because distinct receipts allocate
      // ids and replace the same review-passes/findings artifact. Use the exact
      // canonical lock paths shared by review_pass_set/finding_add so managed
      // and native writers cannot lose one another's updates.
      const storyMetadataLockDir = proposal.conclusion === 'pass'
        ? ctx.store.runtimeLockDirPath(proposal.storyId, 'finding', 'review-passes')
              agent: proposal.providerAgent,
              lane: proposal.lane,
              reviewRunId: proposal.reviewRunId,
              binding: candidate.binding,
              expected,
              evidence: candidate.evidence,
            });
            if (!existingVerification.valid) {
              throw new Error(`managed_review_evidence_import: existing imported evidence is no longer admissible (${existingVerification.reason})`);
            }
          }
          return { importedIds, binding: existingBinding, created: false };
        }

        const importedAt = intake.binding.importedAt;
        const binding = intake.binding;
        let importedIds: string[];
        if (proposal.conclusion === 'pass') {
          const data = ctx.store.readReviewPasses(proposal.storyId);
          const nextNum = data.passes.reduce((max, pass) => {
            const match = pass.id.match(/:RP-(\d+)$/);
            return match ? Math.max(max, Number(match[1])) : max;
          }, 0) + 1;
          const id = `${proposal.storyId}:RP-${String(nextNum).padStart(3, '0')}`;
          const provenance = {
            writerSessionId: `managed:${runId}`,
            sessionSource: 'managed-provider-import',
          };
          const pass: ReviewPass = {
            id,
            agent: proposal.lane,
            note: proposal.note!,
            createdAt: importedAt,
            reviewRound: story.currentReviewRound || '',
            reviewRunId: proposal.reviewRunId,
            ...(reviewRun.envelopeId ? { envelopeId: reviewRun.envelopeId } : {}),
            writerSessionId: provenance.writerSessionId,
            sessionSource: provenance.sessionSource,
            readManifest: proposal.readManifest,
            ...(proposal.readLog ? { readLog: proposal.readLog } : {}),
            ...(proposal.readDiagnostics ? { readDiagnostics: proposal.readDiagnostics } : {}),
            managedEvidenceBinding: binding,
            _hash: signReviewPass(
              proposal.storyId,
              id,
              proposal.lane,
              proposal.note!,
              importedAt,
              story.currentReviewRound || '',
              proposal.reviewRunId,
              proposal.readManifest,
              proposal.readLog,
              proposal.readDiagnostics,
              provenance,
              reviewRun.envelopeId,
              binding,
            ),
          };
          data.passes.push(pass);
          assertLiveReviewMaterial();
          ctx.store.writeReviewPasses(proposal.storyId, data);
          // Persist the receipt-owned evidence identity before sealing its
          // immutable external binding. A crash in the opposite order left a
          // binding for an as-yet-unwritten RP id; another receipt could then
          // allocate that id, making the authentic retry irreconcilable.
          // The existing-evidence branch above repairs the inverse crash
          // window (story persisted, binding not yet sealed) idempotently.
          assertLiveReviewMaterial();
          writeManagedHostRunEvidenceBinding(ctx.root, runId, {
            schemaVersion: 'lattice.managed_review_evidence_import.v1',
            runId,
            receiptId,
            storyId: proposal.storyId,
            reviewRunId: proposal.reviewRunId,
            lane: proposal.lane,
            importedIds: [id],
            importedAt: binding.importedAt,
          });
          importedIds = [id];
        } else {
          const data = ctx.store.readFindings(proposal.storyId);
          const start = data.findings.reduce((max, finding) => {
            const match = finding.id.match(/:F-(\d+)$/);
            return match ? Math.max(max, Number(match[1])) : max;
